
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_am05_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_am05", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.111299241465479e-01, -1.103875115266383e-01, -1.093209926511868e-01, -1.077904237731050e-01, -1.055982071319186e-01, -1.024708169741612e-01, -9.804669828070418e-02, -9.190113416730611e-02, -8.369087850048311e-02, -7.354258449659298e-02, -6.270958086195476e-02, -5.624530936286378e-02, -5.438133079886612e-02, -4.799447201813895e-02, -3.841606382258946e-02, -2.702315827710446e-02, -1.563697301308052e-02, -6.684685739725163e-03, -1.859064250313212e-03, -2.646984476730531e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


